import React, { useState, useEffect, useRef } from "react";
import styles from "./Chat.module.css";

const Chat = () => {
  const [chatHistory, setChatHistory] = useState([]);
  const [userInput, setUserInput] = useState("");
  const [error, setError] = useState("");
  const chatEndRef = useRef(null);

  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    const sentTime = new Date().toLocaleTimeString();
    const newMessage = { sender: "사용자", message: userInput, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);
    setUserInput("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          chatbotName: "챗봇",
          user_input: userInput,
          personality: "T",
        }),
      });

      if (!response.ok) {
        throw new Error("서버 오류");
      }

      const data = await response.json();
      const chatbotMessage = data.response;
      const audioHtml = data.audio_html;

      const receivedTime = new Date().toLocaleTimeString();
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "챗봇", message: chatbotMessage, time: receivedTime, audioHtml: audioHtml }
      ]);
    } catch (error) {
      setError(error.message);
    }
  };

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [chatHistory]);

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatDataTime}>
        <strong>{new Date().toLocaleDateString()}</strong>
      </div>
      <div className={styles.chatHistory}>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender === "사용자" ? styles.chatMessageUser : styles.chatMessageChatbot}>
            <strong>{chat.sender === "사용자" ? "사용자" : "챗봇"}:</strong>
            <div>{chat.message}</div>
            {chat.audioHtml && <div dangerouslySetInnerHTML={{ __html: chat.audioHtml }} />}
            <div className={chat.sender === "사용자" ? styles.chatTimeUser : styles.chatTimeChatbot}>
              <em>{chat.time}</em>
            </div>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && handleSendMessage()}
        />
        <button className={styles.chatSendButton} onClick={handleSendMessage}>전송</button>
      </div>
    </div>
  );
};

export default Chat;
